package com.html2apk.runtime

import android.content.Context
import android.graphics.Color
import org.json.JSONObject

/** Runtime configuration generated by the converter into assets/app_config.json. */
data class AppConfig(
    val sourceType: SourceType,
    /** Relative path inside assets/www for LOCAL, absolute https URL for REMOTE. */
    val entry: String,
    val javaScriptEnabled: Boolean,
    val domStorageEnabled: Boolean,
    val externalLinks: ExternalLinks,
    /** Extra hosts (besides the start host) allowed to load inside the WebView. */
    val allowedHosts: Set<String>,
    val userAgentSuffix: String?,
    val pullToRefresh: Boolean,
    val fileUploads: Boolean,
    /** navigator.share for text and links, through Android's share sheet. */
    val webShare: Boolean,
    /** https, data: and blob: downloads saved to Downloads. */
    val downloads: Boolean,
    /** navigator.share with image and PDF files. */
    val shareFiles: Boolean,
    /** Gallery folder for shared and downloaded images; null means the app name. */
    val galleryFolder: String?,
    /** Package opened directly for file shares instead of the share sheet. */
    val shareTarget: String?,
    /** Page inside assets/www shown instead of the built-in error page. */
    val offlinePage: String?,
    val statusBarColor: Int,
    val navigationBarColor: Int,
    val splash: Splash,
    val theme: Theme,
    /** Hide the status and navigation bars (immersive, swipe to show them). */
    val fullscreen: Boolean,
    val keepScreenOn: Boolean,
    val backButton: BackButton,
    /** Long-press menu on the app icon. */
    val shortcuts: List<Shortcut>,
    /** Ask for the phone's lock (biometric or screen lock) to open the app. */
    val appLock: Boolean,
    /** The web Notification API, shown as Android notifications. */
    val notifications: Boolean,
) {
    enum class SourceType { LOCAL, REMOTE }
    enum class ExternalLinks { BROWSER, BLOCK }
    enum class Theme { LIGHT, DARK, SYSTEM }

    /** [page] is a path inside assets/www (local) or a path or https URL on the site (remote). */
    data class Shortcut(val label: String, val page: String)

    /** Mirrors BackButtonMode in the Dart project model. */
    enum class BackButton { HISTORY, PRESS_TWICE_TO_EXIT, CONFIRM_EXIT, HOME }

    /** [image] is a path inside assets; null means show the app icon. */
    data class Splash(val enabled: Boolean, val backgroundColor: Int, val image: String?)

    companion object {
        const val SUPPORTED_SCHEMA = 1
        const val MAX_SHORTCUTS = 4

        fun load(context: Context): AppConfig {
            val text = context.assets.open("app_config.json").bufferedReader().use { it.readText() }
            return parse(JSONObject(text))
        }

        fun parse(json: JSONObject): AppConfig {
            val schema = json.getInt("schemaVersion")
            require(schema <= SUPPORTED_SCHEMA) { "Unsupported config schema $schema" }
            val source = json.getJSONObject("source")
            val type = when (source.getString("type")) {
                "local" -> SourceType.LOCAL
                "remote" -> SourceType.REMOTE
                else -> throw IllegalArgumentException("Unknown source type")
            }
            val entry = source.getString("entry")
            if (type == SourceType.LOCAL) {
                require(isSafeRelativePath(entry)) { "Invalid entry path" }
            } else {
                require(entry.startsWith("https://")) { "Remote entry must use https" }
            }
            val hosts = json.optJSONArray("allowedHosts")
            val ua = optString(json, "userAgentSuffix")
            val offline = optString(json, "offlinePage")
            require(offline == null || isSafeRelativePath(offline)) { "Invalid offline page path" }
            val splash = json.optJSONObject("splash")
            val splashImage = splash?.let { optString(it, "image") }
            require(splashImage == null || isSafeRelativePath(splashImage)) { "Invalid splash path" }
            return AppConfig(
                sourceType = type,
                entry = entry,
                javaScriptEnabled = json.optBoolean("javaScriptEnabled", false),
                domStorageEnabled = json.optBoolean("domStorageEnabled", false),
                externalLinks = if (json.optString("externalLinks") == "block") ExternalLinks.BLOCK else ExternalLinks.BROWSER,
                allowedHosts = buildSet {
                    if (hosts != null) for (i in 0 until hosts.length()) add(hosts.getString(i).lowercase())
                },
                userAgentSuffix = ua?.takeIf { it.isNotBlank() },
                pullToRefresh = json.optBoolean("pullToRefresh", false),
                fileUploads = json.optBoolean("fileUploads", false),
                webShare = json.optBoolean("webShare", false),
                downloads = json.optBoolean("downloads", false),
                shareFiles = json.optBoolean("shareFiles", false),
                galleryFolder = ShareRules.folderName(optString(json, "galleryFolder")),
                shareTarget = optString(json, "shareTarget")?.takeIf { ShareRules.isPackageName(it) },
                offlinePage = offline,
                statusBarColor = color(optString(json, "statusBarColor"), Color.BLACK),
                navigationBarColor = color(optString(json, "navigationBarColor"), Color.BLACK),
                splash = Splash(
                    enabled = splash?.optBoolean("enabled", false) ?: false,
                    backgroundColor = color(splash?.let { optString(it, "backgroundColor") }, Color.WHITE),
                    image = splashImage,
                ),
                theme = when (optString(json, "theme")) {
                    "dark" -> Theme.DARK
                    "system" -> Theme.SYSTEM
                    else -> Theme.LIGHT
                },
                fullscreen = json.optBoolean("fullscreen", false),
                keepScreenOn = json.optBoolean("keepScreenOn", false),
                backButton = when (optString(json, "backButton")) {
                    "pressTwiceToExit" -> BackButton.PRESS_TWICE_TO_EXIT
                    "confirmExit" -> BackButton.CONFIRM_EXIT
                    "home" -> BackButton.HOME
                    else -> BackButton.HISTORY
                },
                shortcuts = buildList {
                    val list = json.optJSONArray("shortcuts")
                    if (list != null) for (i in 0 until minOf(list.length(), MAX_SHORTCUTS)) {
                        val item = list.optJSONObject(i) ?: continue
                        val label = optString(item, "label")?.trim()?.take(25) ?: continue
                        val page = optString(item, "page") ?: continue
                        if (label.isNotEmpty() && page.length <= 500) add(Shortcut(label, page))
                    }
                },
                appLock = json.optBoolean("appLock", false),
                notifications = json.optBoolean("notifications", false),
            )
        }

        private fun optString(json: JSONObject, key: String): String? =
            if (json.isNull(key)) null else json.optString(key).takeIf { it.isNotEmpty() }

        /** Accepts only #RRGGBB; anything else falls back to [default]. */
        private fun color(value: String?, default: Int): Int =
            if (value != null && Regex("^#[0-9A-Fa-f]{6}$").matches(value)) Color.parseColor(value) else default

        private fun isSafeRelativePath(path: String) =
            path.isNotEmpty() && !path.startsWith("/") && ".." !in path.split('/') && '\\' !in path
    }
}
